import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final int MAX_LIMIT = 1000007;
    static final long MOD_CONST = 1000000007L;
    static int p_input, k_input;
    static int[] cntArr = new int[MAX_LIMIT];
    static int[] visitedArr = new int[MAX_LIMIT];
    static int[] numArr = new int[MAX_LIMIT];
    static List<Integer> divisors_list = new ArrayList<>();

    static void run_dfs(int x, int start) {
        int count = 1;
        while ((long)k_input * x % p_input != start) {
            x = (int)((long)k_input * x % p_input);
            visitedArr[x] = 1;
            count++;
        }
        numArr[count]++;
    }

    static boolean isPrime(int x) {
        if (x < 2) return false;
        for (int i = 2; i * i <= x; i++) {
            if (x % i == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p_input = sc.nextInt();
        k_input = sc.nextInt();

        if (k_input == 0) {
            long total_product = 1;
            for (int i = 1; i < p_input; i++) {
                total_product = (total_product * p_input) % MOD_CONST;
            }
            System.out.println(total_product);
            sc.close();
            return;
        }

        for (int i = 0; i < p_input; i++) {
            if (visitedArr[i] == 0) {
                run_dfs(i, i);
            }
        }

        for (int i = 1; i <= p_input; i++) {
            if (numArr[i] != 0) {
                divisors_list.add(i);
            }
        }

        long final_ans = 1;
        for (int i = 0; i < divisors_list.size(); i++) {
            long temp_sum = 0;
            int divisor_i = divisors_list.get(i);
            for (int j = 0; j < divisors_list.size() && (long)divisors_list.get(j) * divisors_list.get(j) <= divisor_i; j++) {
                int divisor_j = divisors_list.get(j);
                if (divisor_i % divisor_j == 0) {
                    int a = divisor_i / divisor_j;
                    int b = divisor_j;
                    temp_sum += (long) a * numArr[a];
                    if (a != b) {
                        temp_sum += (long) b * numArr[b];
                    }
                    temp_sum %= MOD_CONST;
                }
            }
            int count = numArr[divisor_i];
            for (int j = 0; j < count; j++) {
                final_ans = (final_ans * temp_sum) % MOD_CONST;
            }
        }
        System.out.println(final_ans);
        sc.close();
    }
}
